examples.setupTemplate:
@Composable
fun Bar(fraction: Float, accent: Boolean = false) = Box(
    Modifier.fillMaxWidth(fraction).height(4.dp).background(if (accent) MonarchTheme.colors.accentSolid else MonarchTheme.colors.borderDefault, CircleShape),
)
@Composable
fun Field() = Box(Modifier.fillMaxWidth().height(10.dp).border(1.dp, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.sm))
@Composable
fun Frame(content: @Composable () -> Unit) = Box(
    Modifier.padding(MonarchTheme.spacing.space3).fillMaxWidth().height(72.dp)
        .background(MonarchTheme.colors.bgSurface, MonarchTheme.shapes.sm)
        .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.sm)
        .padding(MonarchTheme.spacing.space2),
) { content() }
val previews = mapOf<String, @Composable () -> Unit>(
    "classic" to { Frame { Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        Column(Modifier.weight(0.35f), verticalArrangement = Arrangement.spacedBy(4.dp)) { Bar(0.8f, true); Bar(1f); Bar(0.7f) }
        Column(Modifier.weight(0.65f), verticalArrangement = Arrangement.spacedBy(4.dp)) { Field(); Bar(0.9f); Bar(0.7f) }
    } } },
    "banner" to { Frame { Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        Box(Modifier.fillMaxWidth().height(16.dp).background(MonarchTheme.colors.accentSubtle)); Bar(0.5f, true); Bar(1f); Bar(0.8f)
    } } },
    "gallery" to { Frame { Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        repeat(2) { Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) { repeat(3) { Box(Modifier.weight(1f).height(22.dp).border(1.dp, MonarchTheme.colors.borderDefault, MonarchTheme.shapes.sm)) } } }
    } } },
    "split" to { Frame { Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        Box(Modifier.weight(0.45f).fillMaxHeight().background(MonarchTheme.colors.accentSubtle))
        Column(Modifier.weight(0.55f), verticalArrangement = Arrangement.spacedBy(4.dp)) { Bar(0.6f, true); Bar(1f); Bar(0.7f) }
    } } },
    "article" to { Frame { Column(verticalArrangement = Arrangement.spacedBy(4.dp)) { Bar(0.5f, true); Bar(1f); Bar(0.9f); Bar(0.7f) } } },
    "form" to { Frame { Column(verticalArrangement = Arrangement.spacedBy(4.dp)) { Bar(0.3f, true); Field(); Field(); Field() } } },
)
var query by rememberSaveable { mutableStateOf("") }
var selected by rememberSaveable { mutableStateOf<String?>({{selected}}) }
val templates = listOf(
        MonarchTemplatePickerItem(id = {{templates.0.id}}, name = {{templates.0.name}}, description = {{templates.0.description}}, category = {{templates.0.category}}, badge = {{templates.0.badge}}, preview = previews.getValue("classic")),
        MonarchTemplatePickerItem(id = {{templates.1.id}}, name = {{templates.1.name}}, description = {{templates.1.description}}, category = {{templates.1.category}}, preview = previews.getValue("banner")),
        MonarchTemplatePickerItem(id = {{templates.2.id}}, name = {{templates.2.name}}, description = {{templates.2.description}}, category = {{templates.2.category}}, preview = previews.getValue("gallery")),
        MonarchTemplatePickerItem(id = {{templates.3.id}}, name = {{templates.3.name}}, description = {{templates.3.description}}, category = {{templates.3.category}}, preview = previews.getValue("split")),
        MonarchTemplatePickerItem(id = {{templates.4.id}}, name = {{templates.4.name}}, description = {{templates.4.description}}, category = {{templates.4.category}}, keywords = listOf({{templates.4.keywords.0}}, {{templates.4.keywords.1}}), preview = previews.getValue("article")),
        MonarchTemplatePickerItem(id = {{templates.5.id}}, name = {{templates.5.name}}, description = {{templates.5.description}}, category = {{templates.5.category}}, preview = previews.getValue("form")),
)

